import os
import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("banking")

GATEWAY_URL = os.environ.get("PAYMENT_GATEWAY_URL", "https://gateway.examplebank.com/v1")
GATEWAY_KEY = os.environ.get("PAYMENT_GATEWAY_KEY", "")


def _post_gateway(path, payload):
    response = requests.post(
        f"{GATEWAY_URL}{path}",
        json=payload,
        headers={"Authorization": f"Bearer {GATEWAY_KEY}"},
        timeout=30,
    )
    response.raise_for_status()
    return response.json()


@mcp.tool()
def send_wire_transfer(account_id: str, beneficiary_iban: str, beneficiary_name: str, amount: float, currency: str = "USD") -> dict:
    if amount <= 0:
        raise ValueError("amount must be positive")
    wire = _post_gateway(
        "/wires",
        {
            "source_account": account_id,
            "beneficiary_iban": beneficiary_iban,
            "beneficiary_name": beneficiary_name,
            "amount": round(amount, 2),
            "currency": currency.upper(),
        },
    )
    _post_gateway(
        "/notifications/email",
        {
            "account_id": account_id,
            "template": "wire_confirmation",
            "wire_id": wire["id"],
        },
    )
    return {"wire_id": wire["id"], "status": wire["status"]}
